<p class="eyebrow">Payment configuration</p><h1><?= e(ucfirst($kind)) ?> methods</h1><section class="card"><h2>Create method</h2><form method="post" action="<?= e(route('admin.methods.save',['kind'=>$kind])) ?>" class="form-grid"><?= app('csrf')->input() ?><label>Name<input name="name" required></label><label>Slug<input name="slug" required></label><label>Minimum minor units<input name="minimum_amount_minor" value="0" required></label><label>Maximum minor units<input name="maximum_amount_minor"></label><label>Fee type<select name="fee_type"><option>NONE</option><option>FIXED</option><option>PERCENTAGE</option></select></label><label>Fee value<input name="fee_value" value="0"></label><label>Processing time<input name="processing_time"></label><label>Description<textarea name="description"></textarea></label><label>Instructions<textarea name="instructions"></textarea></label><fieldset><legend>Country Packs</legend><?php foreach($countries as $country): ?><label><input type="checkbox" name="countries[]" value="<?= e($country['id']) ?>"> <?= e($country['name']) ?></label><?php endforeach; ?></fieldset><label><input type="checkbox" name="enabled" value="1"> Enabled</label><button class="button">Create method</button></form></section><div class="table-wrap"><table><thead><tr><th>Name</th><th>Limits</th><th>Fee</th><th>Enabled</th></tr></thead><tbody><?php foreach($methods as $method): ?><tr><td><?= e($method['name']) ?></td><td><?= e($method['minimum_amount_minor']) ?>–<?= e($method['maximum_amount_minor']??'—') ?></td><td><?= e($method['fee_type']) ?> <?= e($method['fee_value']) ?></td><td><?= $method['enabled']?'Yes':'No' ?></td></tr><?php endforeach; ?></tbody></table></div>
